<?= $this->include('layouts/header') ?><div class="page-head"><div><div class="page-kicker">Control trail</div><h1 class="page-title">Audit log</h1><p class="page-subtitle">Who changed what, when, and from where.</p></div></div><div class="card"><div class="toolbar"><div class="section-meta">Sensitive actions and data changes are retained for traceability.</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Date/time</th><th>User</th><th>Action</th><th>Module</th><th>Record</th><th>Description</th><th>IP</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7"><div class="empty"><strong>No audit events</strong>Activity will appear after users start making changes.</div></td></tr><?php else: foreach($rows as $r): ?><tr><td><?=esc($r['created_at'])?></td><td><?=esc($r['user_name']??'System')?></td><td><span class="badge primary"><?=esc($r['action'])?></span></td><td><?=esc($r['module'])?></td><td><?=esc($r['record_id']??'—')?></td><td style="white-space:normal;min-width:280px"><?=esc($r['description'])?></td><td class="mono"><?=esc($r['ip_address'])?></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?= $this->include('layouts/footer') ?>